function drawWorld(){
 // grass and borders
 for(let my=0;my<17;my++)for(let mx=0;mx<30;mx++){let n=(mx*17+my*31)%5;drawTile(mx,my,n===0?'#73b94f':'#78b951',n===0?'#65aa48':'#86c85c')}
