}
function drawShop(px,py,w,h){drawHouse(px,py,w,h,'#f2dfb1','#798c55','#6b6740','');x.fillStyle='#4d3b31';rect(px+22,py+48,126,14);x.fillStyle='#f1b95c';rect(px+35,py+78,100,38);x.fillStyle='#9a6c3d';rect(px+30,py+72,110,8);x.fillStyle='#fff1ca';rect(px+46,py+86,78,12)}
