function drawTree(px,py,stump){if(stump){x.fillStyle='#795738';rect(px+9,py+13,16,14);return}x.fillStyle='#59472f';rect(px+13,py+23,10,30);x.fillStyle='#4f8b43';rect(px-4,py-2,44,43);x.fillStyle='#67a64e';rect(px+7,py-12,24,22);x.fillStyle='#79b95a';rect(px+3,py+2,9,8);rect(px+24,py+9,7,8)}
