function drawPumpkin(px,py){x.fillStyle='#44843d';rect(px-3,py-8,6,10);x.fillStyle='#d87d2f';rect(px-11,py-2,22,15);x.fillStyle='#ef9b44';rect(px-6,py+1,12,10)}
function drawCrop(c){if(c.stage===0){x.fillStyle=c.water?'#80603c':'#97764c';rect(c.x,c.y,32,32);return}x.fillStyle=c.water?'#4e8d45':'#678d3e';if(c.stage===1){rect(c.x+14,c.y+12,4,14);rect(c.x+8,c.y+10,7,5);rect(c.x+18,c.y+7,7,5)}else if(c.stage===2){x.fillStyle='#4f8d43';rect(c.x+10,c.y+3,12,22);x.fillStyle='#98bd3d';rect(c.x+5,c.y+8,8,8);rect(c.x+20,c.y+12,8,8)}else{x.fillStyle='#78ad48';rect(c.x+8,c.y+2,16,24);x.fillStyle='#d8d4b1';rect(c.x+4,c.y+8,24,7);rect(c.x+9,c.y+17,14,7);rect(c.x+1,c.y+13,8,7);rect(c.x+23,c.y+17,8,7)}}
function drawNPC(px,py,hair,shirt,skin){x.fillStyle='#503e30';rect(px-12,py+20,24,10);x.fillStyle=skin;rect(px-9,py-7,18,17);x.fillStyle=hair;rect(px-11,py-13,22,7);rect(px-11,py-8,5,10);x.fillStyle=shirt;rect(px-10,py+10,20,22);x.fillStyle='#263e4b';rect(px-7,py+30,7,10);rect(px+1,py+30,7,10)}
