 x.fillStyle='#4d7b45';rect(px-12,py+bob,24,22);x.fillStyle='#d5aa78';rect(px-8,py-14-bob,16,16);x.fillStyle='#6d4432';rect(px-10,py-18-bob,20,8);rect(px-10,py-13-bob,5,10);
 x.fillStyle='#263e4b';rect(px-7,py+35-bob,7,7);rect(px+2,py+35-bob,7,7);
 if(tools[selected]==='Hoe'||tools[selected]==='Axe'||tools[selected]==='Water'){x.fillStyle=tools[selected]==='Water'?'#9ab5cf':'#6e5a43';rect(px+(player.facing==='left'?-18:13),py+8,4,20);x.fillStyle='#b6b39d';if(toinspector()){} }
