 // bottom inventory
 x.fillStyle='rgba(47,72,53,.85)';rect(270,484,420,48);for(let i=0;i<8;i++){x.fillStyle=i===selected?'#e0c47c':'#9a8057';rect(278+i*50,492,44,32);x.strokeStyle='#5e4c38';x.lineWidth=2;x.strokeRect(278+i*50,492,44,32)}
 for(let i=0;i<tools.length;i++){drawItem(i,286+i*50,496)}
 pixelText(coins+'g',918,40,24,'#ffe28a','right');x.fillStyle='#4d402f';rect(840,56,96,13);x.fillStyle='#70bd68';rect(842,58,92*(energy/100),9);
 pixelText('Energy',842,82,15,'#f4d9b0','right');
 if(toastT>0){x.fillStyle='rgba(55,45,38,.9)';rect(315,100,330,38);pixelText(toast,480,126,20,'#fff4c9','center')}
}
function drawItem(i,px,py){x.fillStyle='#5b4a38';pixelText(String(i+1),px-2,py+7,11,'#fff');if(i===0){x.fillStyle='#8b6542';rect(px+20,py+14,18,4)}if(i===1){x.fillStyle='#d9c68c';rect(px+21,py+10,14,15);x.fillStyle='#73a64c';rect(px+24,py+8,8,5)}if(i===2){x.fillStyle='#d4d7cf';rect(px+20,py+10,16,17);x.fillStyle='#84b8ca';rect(px+23,py+14,10,10)}if(i===3){x.fillStyle='#6d5038';rect(px+20,py+10,5,18);x.fillStyle='#aab0a3';rect(px+17,py+8,10,5)}}
