function showToast(s){toast=s;toastT=120}
function use(){
 let tx=player.x,ty=player.y+18;
 if(tools[selected]==='Seeds'){for(const c of crops){if(Math.abs(c.x-tx)<24&&Math.abs(c.y-ty)<24&&c.stage===0){c.stage=1;c.water=false;showToast('Seeds planted');energy-=2;return}}showToast('Plant in the soil')}
 if(tools[selected]==='Water'){for(const c of crops){if(Math.abs(c.x-tx)<28&&Math.abs(c.y-ty)<28&&c.stage>0){c.water=true;showToast('Crop watered');energy-=1;return}}}
 if(tools[selected]==='Hoe'){for(let i=crops.length-1;i>=0;i--){let c=crops[i];if(Math.abs(c.x-tx)<25&&Math.abs(c.y-ty)<25&&c.stage>0){if(c.stage>=3){coins+=18;c.stage=0;c.water=false;showToast('Parsnip sold for 18g');energy-=2}else showToast('Needs more time')}}}
 if(tools[selected]==='Axe'){for(let i=trees.length-1;i>=0;i--){let t=trees[i];if(Math.abs(t.x-tx)<30&&Math.abs(t.y-ty)<35&&!t.stumps){t.stumps=true;inv[2].q++;coins+=2;showToast('Wood collected');energy-=3;return}}}
}
let last=performance.now();function loop(now){let dt=Math.min(32,now-last);last=now;
 let sp=0.16*dt,dx=(keys.d?1:0)-(keys.a?1:0),dy=(keys.s?1:0)-(keys.w?1:0);if(dx&&dy){dx*=.707;dy*=.707}
 if(dx||dy){player.dx=dx;player.dy=dy;if(dx<0)player.facing='left';if(dx>0)player.facing='right';if(dy<0)player.facing='up';if(dy>0)player.facing='down';player.step+=dt}
 player.x=Math.max(20,Math.min(940,player.x+dx*sp));player.y=Math.max(42,Math.min(500,player.y+dy*sp));
 time+=dt*.00018;if(time>=24){time=7;day++;for(const c of crops)if(c.stage>0&&c.stage<3&&c.water)c.stage++;for(const c of crops)c.water=false;energy=100;showToast('Good morning!')}
